"""Layer 15 MLP hidden unit 3720 (read through one rank-one component), as a word-class rule.

The component reads the MLP hidden unit 3720 of layer 15 and writes it back into the residual
stream. Its activation is mostly small and noisy, and most of its variance is not explained by
the current word at all. What the word does explain is a weak pattern: the activation is
highest on words that open a clause or a noun phrase that is still being built (relative and
subordinating words, possessive and demonstrative determiners, numerals), and near zero on
articles and auxiliaries. Everything else gets the average activation.

This program predicts a constant per word class, using the class means measured on training
rows. It has no memory of earlier tokens.
"""

READS = ()

# Relative pronouns, wh-words and subordinating conjunctions.
WH_AND_SUBORDINATORS = {
    "which", "who", "whom", "whose", "why", "since", "though", "although", "how", "where",
    "when", "because", "so", "that", "qui", "que",
}
# Possessive and demonstrative determiners, and a few quantifiers that take a noun next.
POSSESSIVE_AND_DEMONSTRATIVE = {
    "his", "her", "its", "our", "their", "my", "these", "those", "this", "such", "many",
    "several", "both", "few", "each", "other",
}
# Cardinal numerals.
NUMERALS = {"two", "three", "four", "five", "six", "seven", "eight", "nine", "ten", "million"}
# Articles, auxiliaries and negation: little or no activation.
ARTICLES_AND_AUXILIARIES = {
    "a", "an", "the", "is", "was", "be", "not", "are", "were", "been", "no", "some", "all",
    "any", "every",
}

# Class means measured on 16,384 training rows (mean activation of each class's tokens).
CLASS_VALUE = {
    "wh": 0.54,
    "possessive": 0.39,
    "numeral": 0.75,
    "article": 0.0,
    "other": 0.05,
}


def word_class(word: str) -> str:
    if word in WH_AND_SUBORDINATORS:
        return "wh"
    if word in POSSESSIVE_AND_DEMONSTRATIVE:
        return "possessive"
    if word in NUMERALS:
        return "numeral"
    if word in ARTICLES_AND_AUXILIARIES:
        return "article"
    return "other"


def step(carry, prefix, upstream):
    # The word being read at this position: the newest token, decoded alone.
    word = prefix.token_strings[-1].strip().lower()
    return carry, CLASS_VALUE[word_class(word)]

"""Layer 15, MLP hidden unit 3722 (the down_proj component 3722), as a readable rule.

The unit sits near zero almost everywhere (typical values -0.5 to 0.5, noisy from token to
token). Its large positive values come where the text is about what someone wants, tries,
claims or is entitled to do, or about a person's own self: the "to" after such a verb
("tried to", "claim to", "entitled to", "attempt to"), reflexives and self-references
("himself", "own", "I'm", "am"), and the subject that opens a reported clause after a verb of
saying or thinking ("said he", "thought they", "claimed she"). Pronouns and possessives in
general sit a little above zero. This program predicts the average value of each of these
groups and the baseline everywhere else. It explains only a little of the variance: the
unit's values are not carried by any simple word class I could find.
"""

SELF = {"am", "'m", "’m", "own", "himself", "herself", "themselves", "myself", "yourself", "自己"}
PRONOUN = {"he", "she", "they", "i", "we", "his", "her", "their", "its", "my", "our", "him", "them", "我"}
INTENT = {"claim", "claimed", "claiming", "claims", "try", "tried", "trying", "tries", "attempt",
          "attempted", "attempts", "attempting", "sought", "want", "wanted", "wants", "desire",
          "plan", "planned", "determined", "entitled", "right"}
SAYING = {"said", "says", "say", "claimed", "claims", "thought", "think", "believe", "believed",
          "knew", "insisted", "argued", "felt", "feel"}
BASELINE = -0.012
READS = ()


def word(token):
    return token.strip().lower()


def step(carry, prefix, upstream):
    cur = word(prefix.token_strings[-1])
    same_doc = len(prefix.document_ids) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]
    prev = word(prefix.token_strings[-2]) if same_doc else ""
    if cur == "to" and prev in INTENT:
        value = 0.65
    elif cur in SELF:
        value = 0.34
    elif cur in PRONOUN and prev in SAYING:
        value = 1.6
    elif cur in INTENT:
        value = 0.12
    elif cur in PRONOUN:
        value = 0.09
    else:
        value = BASELINE
    return carry, value

"""Layer 15 MLP down_proj, component 3729: a negative "end of a unit" detector.

Most tokens leave this component near zero. It goes negative on tokens that close a
unit of text, and the more a unit closes, the more negative:
  - the end of a chat turn or tool call (<|im_end|>, </tool_call>): strongest;
  - a line break that follows a closing mark (')', ']', '}', ';', '`', a closing quote
    or period), including an escaped line break written as a backslash-n inside a
    string, as in '}\n' or ');\\n': strongly negative;
  - a closing mark or period at the end of a text, and line breaks or runs of
    indentation (tabs, several spaces) that do not follow one: mildly negative;
  - a single space or a comma: almost nothing.
Ordinary words predict zero.

The program reads only the newest token. Each class has a fixed value, about the mean
activation of its tokens over several hundred thousand tokens of training text.
"""

CHAT_MARKERS = {"<|im_end|>", "</tool_call>", "</tool_response>"}
CLOSING_MARKS = set(")]};`。”!?")


def is_closer(text):
    """True if the text ends in a closing mark: a bracket, semicolon, backtick, or a
    period or quote that closes (' "' opens a quote, so it does not count)."""
    s = text.rstrip()
    if not s:
        return False
    last = s[-1]
    if last in CLOSING_MARKS:
        return True
    return last in ".\"'" and not text.startswith(" ")


def strip_escape(text):
    """Text before an escaped line break (a backslash, optionally then 'n')."""
    if text.endswith("\\n"):
        return text[:-2]
    if text.endswith("\\"):
        return text[:-1]
    return text


def is_line_break(text):
    """A newline, or an escaped newline written as a backslash (optionally then 'n')."""
    return "\n" in text or strip_escape(text) != text


def step(carry, prefix, upstream):
    t = prefix.token_strings[-1]
    if t in CHAT_MARKERS:
        value = -10.6
    elif is_line_break(t) and is_closer(strip_escape(t)):
        value = -6.3
    elif is_closer(t) or t == "." or is_line_break(t) or (t.strip() == "" and t != " "):
        value = -2.3
    elif t in (" ", ","):
        value = -0.2
    else:
        value = 0.0
    return carry, value


READS = ()

"""Layer 15, MLP hidden unit 3732 of Qwen3-1.7B, read from the last few words.

The component reads mostly that one hidden unit (about two-thirds of its input
weight's squared norm), so its activation is roughly that unit's value. The unit
is near 0.04 on average and is above 2 on under half a percent of
tokens. Those tokens open a phrase that sets up the topic being examined or
reasoned about:

  - the word after a framing phrase: "depending ON", "based ON", "looking AT",
    "according TO", "due TO", "given THE", "regarding THE"
  - the word after a verb of checking or considering: "check THE", "understand
    HOW", "let me SEE", "verify WHAT", "review THE"
  - "of" after a topic noun: "the nature OF", "definition OF", "description OF"
  - the wh-words "how" and "what" (mildly), and "the" after a preposition (weakly)
  - slightly negative on "other" after "and"/"or" ("any other ...")

Each branch predicts the mean activation seen for it on training text, and every
other token predicts the overall mean. Most of the unit's variance sits on ordinary
tokens with no nameable pattern, so this rule table explains only about 2% of it.
"""

READS = ()

BASE = 0.04
FRAMING_STRONG = {"depending", "depends", "based", "looking", "look"}
FRAMING_WEAK = {"due", "according", "given", "regarding", "concerning", "owing"}
CONSIDER = {
    "check", "checks", "checking", "see", "think", "verify", "review", "understand",
    "understanding", "consider", "considering", "examine", "analyze", "explain", "recall",
    "reflect",
}
PREPOSITIONS = {
    "of", "to", "on", "in", "at", "with", "for", "by", "from", "about", "into", "over",
    "under", "through", "upon", "within", "during", "without", "across", "among", "against",
    "after", "before", "between", "regarding", "concerning",
}
NEXT_TOPIC = {"on", "at", "to", "of", "the", "how", "what", "in", "about"}
TOPIC_NOUNS = {"nature", "description", "definition", "structure", "examination", "interpretation", "consideration"}
WH = {"how", "what"}


def _word(text):
    return text.strip().lower()


def step(carry, prefix, upstream):
    tokens, docs = prefix.token_strings, prefix.document_ids
    cur = _word(tokens[-1])
    prev = ""
    if len(tokens) >= 2 and docs[-2] == docs[-1]:
        prev = _word(tokens[-2])
    if prev == "me" and cur in CONSIDER:
        value = 2.6
    elif prev in FRAMING_STRONG and cur in NEXT_TOPIC:
        value = 1.7
    elif prev in FRAMING_WEAK and cur in NEXT_TOPIC:
        value = 1.2
    elif prev in CONSIDER and cur in NEXT_TOPIC:
        value = 1.6
    elif prev in TOPIC_NOUNS and cur == "of":
        value = 2.5
    elif prev in {"and", "or"} and cur == "other":
        value = -1.4
    elif cur in WH:
        value = 0.6
    elif cur == "the":
        value = 0.4 if prev in PREPOSITIONS else 0.08
    else:
        value = BASE
    return carry, value

"""Relation-slot and description detector for layers.15 MLP unit 3741 (v4).

Its input reads mainly MLP hidden unit 3741 of layer 15, so its activation tracks how
strongly that unit fires at each token. Most of its variance is diffuse, token-level
noise that a short program cannot name. This program covers the large, nameable part:
the places where the text states a relation or describes a character.

Three rules, each predicting the average activation of the tokens it picks out:

1. Knowledge-base lines, "subject | relation | object" or "subject -> relation -> object"
   (also " — "). The relation slot, between the first and second separator, is where the
   unit fires: relation words such as "place of birth", "country of citizenship",
   "instance of", "member of", "located in ..." give about 6; the word after one about 5;
   separators about 1.5; other words in such a line about 0.2.
2. Relation words outside such lines (e.g. "country", "birth") give about 1.8.
3. Summaries describing a character or speaker ("The speaker believes the character is
   scary"). For 30 tokens after "speaker" or "character", reporting or describing verbs
   ("mentions", "thinks", "depicted") give about 6.5, predicate words ("is", "as", "in",
   "a") about 1.2, and other words about 0.5.
Everything else gets the baseline 0.05.
"""
READS = ()

RELATION_WORDS = {' ' + w for w in (
    'country place birth death citizenship instance occupation member located entity border '
    'name educated held given position shares').split()}
REPORT_VERBS = {' ' + w for w in (
    'mentions plans thinks says believes explains notes starts describes described depicted '
    'wants shows feels looks should').split()}
PREDICATE_WORDS = {' ' + w for w in ('is are be being as in like a the').split()}
SUBJECT_WORDS = {' speaker', ' character', ' characters'}
SEPARATORS = {' |', ' ->', ' —'}
SPEAKER_SPAN = 30  # tokens after "speaker"/"character" that count as its description


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    doc = prefix.document_ids[-1]
    if carry is None or carry[2] != doc:
        carry = ('', -10**9, doc)  # a new document forgets the line and the subject
    line, last_subject, _ = carry
    t = prefix.position
    prev = prefix.token_strings[-2] if t > 0 and prefix.document_ids[-2] == doc else ''
    line = '' if '\n' in tok else (line + tok)[-200:]
    if tok in SUBJECT_WORDS:
        last_subject = t
    in_kb = any(s in line for s in (' | ', ' -> ', ' — ', '->', '|'))
    v = 0.05
    if in_kb:
        if tok in RELATION_WORDS:
            v = 6.4
        elif prev in RELATION_WORDS:
            v = 4.8
        elif tok in SEPARATORS:
            v = 1.5
        else:
            v = 0.15
    elif tok in RELATION_WORDS:
        v = 1.8
    if t - last_subject <= SPEAKER_SPAN:
        if tok in REPORT_VERBS:
            v = 6.5
        elif tok in PREDICATE_WORDS:
            v = 1.2
        elif v < 0.5:
            v = 0.5
    return (line, last_subject, doc), v

"""Component p-82af68dd@100000/layers.15.mlp.down_proj:3756: a diffuse, mostly unexplained readout.

What it does: its activation is a dense linear readout of layer 15's MLP hidden state. Across the
training data it is close to zero-mean noise (std about 0.86), and almost none of it is predictable from
tokens. Token identity, the preceding tokens, and position explain only about 2% of its variance out of
sample, so this program predicts only the parts that are simple to state:

  * the first token of each document: the component is silent there (about 0);
  * chat and document markers (<|endoftext|>, <|im_end|>, <think>, </think>, ...): about -0.9;
  * every other token: the average, about -0.02.

Explained variance is roughly 0.3%. Nothing in the program is a causal account of the component.
"""

READS = ()

MARKERS = {"<think>", "</think>"}
MARKER_VALUE = -0.9  # mean activation at chat/document markers
ORDINARY_VALUE = -0.02  # mean activation on ordinary tokens


def is_marker(tok):
    return tok.startswith("<|") or tok in MARKERS


def step(carry, prefix, upstream):
    doc = prefix.document_ids[-1]
    if carry is None or doc != carry[0]:
        pos = 0  # first token of a document
    else:
        pos = carry[1] + 1
    if pos == 0:
        value = 0.0
    elif is_marker(prefix.token_strings[-1]):
        value = MARKER_VALUE
    else:
        value = ORDINARY_VALUE
    return (doc, pos), value


def main():
    """Run the program on a token list and print its predictions (for a quick look)."""
    import sys

    toks = sys.argv[1:]
    carry = None
    for i, tok in enumerate(toks):
        class P:  # minimal prefix stand-in: one document, all tokens
            document_ids = [0] * (i + 1)
            token_strings = toks[: i + 1]
        carry, value = step(carry, P, {})
        print(f"{tok!r:20} {value:+.2f}")


if __name__ == "__main__":
    main()

"""Component layers.15.mlp.down_proj:3771 (Qwen3-1.7B).

Plain-terms summary: this component goes negative on the token that OPENS an
aside, a parenthetical or a code comment. It is most negative when an opening
parenthesis follows a word of ordinary prose: "...the tube (optional, default
is ...", "...as seen by A (". Code comment openers (" //", " /*", " #") and aside
dashes (" –", " —") are also strongly negative, and a question mark, a colon or
a sentence-ending period are mildly negative. Everything else is treated as 0:
the activation there is small and varies with context this program cannot see.

Its output direction promotes words that follow a definition or gloss ("called",
"referred", "which", "this"), so a negative activation at an aside opener
suppresses those continuations.

Each value is the mean activation of its token class, measured on 4096 training
rows of 512 tokens. Stateless: reads only the newest token and the one before it.
"""

READS = ()

PAREN = {" (", "（"}
COMMENT = {" //", " /*", " #", " ///"}
DASH = {" –", " —"}
QUESTION = {"?"}
PERIOD = {".", ".\n", ".\n\n"}
COLON = {":"}


def after_word(prev):
    """True if the previous token ends in a letter, digit or closing quote or bracket."""
    last = prev.rstrip()[-1:]
    return last.isalnum() or last in "\"'”’)"


def step(carry, prefix, upstream):
    tok = prefix.token_strings[-1]
    prev = ""
    if len(prefix.token_strings) > 1 and prefix.document_ids[-2] == prefix.document_ids[-1]:
        prev = prefix.token_strings[-2]
    if tok in PAREN:
        value = -2.3 if after_word(prev) else -0.8
    elif tok in COMMENT:
        value = -2.7
    elif tok in DASH:
        value = -1.5
    elif tok.strip() in QUESTION:
        value = -1.5
    elif tok in PERIOD:
        value = -0.2
    elif tok in COLON:
        value = -0.4
    else:
        value = 0.0
    return carry, float(value)
